# owner: platform
"""Seating rows built from a list of students."""

from typing import List

from rosterkit.models import Student
from rosterkit.errors import ProjectError


def _sort_key(stud: Student) -> tuple:
    return (stud.last_name.lower(), stud.first_name.lower())


def _name(stud: Student) -> str:
    return f"{stud.last_name}, {stud.first_name}"


def _chunks(items: list, size: int) -> list:
    return [
        items[pos:pos + size]
        for pos in range(0, len(items), size)
    ]


def _render(rows: list) -> List[str]:
    lines = []
    for index, group in enumerate(rows, 1):
        names = " | ".join(map(_name, group))
        lines.append(f"Row {index}: {names}")
    return lines


# ---
def seat_rows(
    students: List[Student], seats: int
) -> List[str]:
    if seats < 1 or not students:
        raise ProjectError("need students and seats")
    ordered = sorted(students, key=_sort_key)
    return _render(_chunks(ordered, seats))
EOF
